                        "last_visit": dates[-1] if dates else None,
                        "favorite_services": [t for t, _ in svc_counter.most_common(4)],
                        "avg_cycle_days": cycle,
                        "total_spent": total_spent,
                        "preferences": prefs or "(пока ничего не запомнено)",
                        "note": "Телефон не показывай. Это история и привычки клиента — для тёплого приёма и совета.",
                    }
        else:
            result = {"error": f"Неизвестный инструмент: {tool_name}"}
    except Exception as e:
        result = {"error": str(e)}

    if isinstance(result, dict) and result.get("unknown") is True:
        result = {
            **result,
            "retry_allowed": False,
            "user_message": (
                "Результат операции уточняется. Не повторяйте действие, "
                "пока MAYA не проверит его состояние."
            ),
        }

    logger.info(f"📦 Результат {tool_name}: {str(result)[:200]}")
    return json.dumps(result, ensure_ascii=False)

def _authorize(role: str, tool_name: str, mode: str | None = None) -> bool:
    """Второй рубеж: вправе ли роль вызвать инструмент. Детерминированно."""
    if tool_name in _surface_disabled_tools(mode):
        return False
    return tool_name in _allowed_tool_names(role, mode)

def _tool_risk(tool_name: str) -> str:
    if tool_name in _HITL_TOOLS:
        return "money"
    if tool_name in _WRITE_TOOLS:
        return "write"
    return "read"

def get_slot_waitlist(staff_id: int, slot_iso: str, tolerance_min: int = 20) -> list[dict]:
    """Клиенты, ждавшие этот (или близкий ±tolerance_min) слот у мастера, кому
    ещё не писали. [{id, client_id, chat_id, slot_datetime}]."""
    from datetime import datetime as _dt
    slot_iso = (slot_iso or "")[:16]
    try:
        target = _dt.fromisoformat(slot_iso)
    except Exception:
        return []
    day = slot_iso[:10]
    with _db() as conn:
        rows = conn.execute(
            "SELECT id, client_id, chat_id, slot_datetime FROM slot_waitlist "
            "WHERE staff_id=? AND notified_at IS NULL AND substr(slot_datetime,1,10)=?",
            (staff_id, day),
        ).fetchall()
    out = []
    for r in rows:
        try:
            t = _dt.fromisoformat(r["slot_datetime"][:16])
        except Exception:
            continue
        if abs((t - target).total_seconds()) <= tolerance_min * 60:
            out.append({"id": r["id"], "client_id": r["client_id"],
                        "chat_id": r["chat_id"], "slot_datetime": r["slot_datetime"]})
    return out

def get_or_create_ref_code(client_id: int) -> str:
    """Возвращает реферальный код клиента, создаёт при первом вызове."""
    existing = database.get_referral_code(client_id)
    if existing:
        return existing
    raise RuntimeError("p4_04_legacy_mutation_disabled:issue_referral_link")
    # Уникальный код. Пытаемся несколько раз на случай коллизии.
    for _ in range(10):
        token = "REF-" + _gen_short_token(6)
        if database.is_ref_code_free(token):
            database.create_ref_code(client_id, token)
            return token
    raise RuntimeError("Не получилось сгенерировать уникальный реферальный код")
